import{_ as t,o as e,c as o,a5 as a}from"./chunks/framework.BPFk9-tb.js";const m=JSON.parse('{"title":"写作课作业-096","description":"","frontmatter":{"date":"2020-10-24T05:10:55","title":"写作课作业-096","categories":["写作","作业"],"tags":["写作","作业"]},"headers":[],"relativePath":"posts/homework/094.md","filePath":"posts/homework/094.md"}'),r={name:"posts/homework/094.md"};function s(_,p,c,n,i,l){return e(),o("div",null,[...p[0]||(p[0]=[a("<blockquote><p>10月23日作业 什么是当前最让你焦虑的？你用什么样的应对方法来处理这种焦虑？ 如果你朝着自己的目标改变了，你会有什么新的焦虑？你准备如何应对这种焦虑？</p></blockquote><blockquote><p>当前最让自己焦虑的是房贷还不上。</p></blockquote><p>其实这个焦虑是多个层面引起的，比如自己的发展到了某个平台期，刚经历小打小闹型的创业失败，小孩的成长需要金钱和精力，房贷占收入比重过大，除了房贷还有外债，想买BOX却没余钱。</p><p>国庆后逐步恢复上班，发现就是让自己动起来，按规律的生活和工作，毕竟房贷他很有规律啊。</p><p>发现自己心情陷入不好时，能运动时候就去运动，让自己产生点多巴胺。</p><blockquote><p>次级焦虑时投入不少时间学习、写作没看到收益。</p></blockquote><p>之前有个作业是，自己如果放弃写作是因为什么，我是这么写的“会放弃最可能的原因是投入时间大，但收效甚微。”</p><p>虽然知道“要勇于去做做很久才能看到收益的事情。”自己其实也是个表现型人格，比较在意家人的看法，那这段时间因为买房不肯卖BOX，那就被冠上学习，写作无用的时候，自己其实挺低迷。</p><p>暂时没想到什么办法，只能告诉自己慢慢来。</p><p>自己是会成为猛人的，那猛人有什么特质呢？猛人勇于去做做很久才能看到收益的事情。</p><p>才写不到100篇，你觉得猛么？不猛。</p><p>写的内容也短短的，你觉得猛么？不猛。</p><p>写的内容还不通顺，你觉得猛么？不猛。</p><p>这么多不猛，那还有什么好说的，写就是了。那还有什么好焦虑的，写就是了。</p><p>想办法找到「遥远的光」，在焦虑中继续鼓励勇气前进。</p><hr><p>欢迎联系我</p><p>微信号 ：Crazy_Airhead</p><p>Mixin ID : 1091586</p><p>定投课堂邀请码：6DYMBFP061</p><p>李笑来写作课邀请码：38MDGFYZK8</p><p>水龙头邀请码：FDJQHJ</p>",22)])])}const k=t(r,[["render",s]]);export{m as __pageData,k as default};
